//! Vector001: fixed-point 3D vector arithmetic: sums, cross products and dot products of random vectors.
//! Generated by `dotnet run --project Runner -c Release -- generate`; change the generator, not this file.
use crate::common::{rotl, Rng};

#[derive(Clone, Copy)]
struct Vec3 {
    x: u64,
    y: u64,
    z: u64,
}

impl Vec3 {
    fn new(x: u64, y: u64, z: u64) -> Self {
        Vec3 { x, y, z }
    }

    fn add(self, other: Vec3) -> Vec3 {
        Vec3::new(self.x.wrapping_add(other.x), self.y.wrapping_add(other.y), self.z.wrapping_add(other.z))
    }

    fn scale(self, factor: u64) -> Vec3 {
        Vec3::new(self.x.wrapping_mul(factor), self.y.wrapping_mul(factor), self.z.wrapping_mul(factor))
    }

    fn dot(self, other: Vec3) -> u64 {
        self.x
            .wrapping_mul(other.x)
            .wrapping_add(self.y.wrapping_mul(other.y))
            .wrapping_add(self.z.wrapping_mul(other.z))
    }

    fn cross(self, other: Vec3) -> Vec3 {
        Vec3::new(
            self.y.wrapping_mul(other.z).wrapping_sub(self.z.wrapping_mul(other.y)),
            self.z.wrapping_mul(other.x).wrapping_sub(self.x.wrapping_mul(other.z)),
            self.x.wrapping_mul(other.y).wrapping_sub(self.y.wrapping_mul(other.x)),
        )
    }
}

fn simulate(seed: u64) -> u64 {
    let mut rng = Rng::new(seed);
    let mut sum = Vec3::new(0, 0, 0);
    for _ in 0..22 {
        let x = rng.next();
        let y = rng.next();
        let z = rng.next();
        let v = Vec3::new(x, y, z);
        let w = v.cross(sum).add(v.scale(0x46FC33FF15BEF56B));
        sum = sum.add(w);
        if sum.dot(v) & 1 == 1 {
            sum = sum.scale(0xDD4AAB4072C7E9);
        }
    }
    sum.dot(sum) ^ sum.x
}

fn kernel_a(x: u64, y: u64) -> u64 {
    let mut a: u64 = x & (y << 6);
    let mut b: u64 = y >> 47;
    for i in 0..6u64 {
        a = a.wrapping_add(i).wrapping_mul(i ^ b);
        b = b.wrapping_mul(rotl(i << 49, 12));
        if ((a.wrapping_sub(156)) & 1023) != 523 {
            a = a | ((b | 0x3376D34B666D4591) % 728);
        } else {
            b = b.wrapping_mul(a).wrapping_add(b ^ 154);
        }
    }
    if ((b.wrapping_mul(x)) & 1023) == 529 {
        a = a & ((b.wrapping_sub(88)) >> 26);
    } else {
        b = b | a.wrapping_add(x);
    }
    let c: u64 = x.wrapping_add(b.wrapping_mul(55));
    c ^ a.wrapping_add(b)
}

fn kernel_b(x: u64, y: u64) -> u64 {
    let mut a: u64 = rotl(x, 27);
    let mut b: u64 = y & 255;
    for i in 0..6u64 {
        a = a.wrapping_sub(b.wrapping_add(x).wrapping_add(b & 118));
        b = rotl(b, 18).wrapping_sub(b << 21);
        if ((i ^ b) & 65535) > 34281 {
            a = a.wrapping_sub((i >> 55).wrapping_add(0xA01421F728036A41));
        } else {
            b = rotl(b.wrapping_mul(158), 12);
        }
    }
    let c: u64 = rotl(a, 16) << 8;
    let d: u64 = (b << 1) & (a ^ 40);
    (c ^ (a ^ b)).wrapping_add(d)
}

pub fn mix(x: u64) -> u64 {
    kernel_b(kernel_a(x, 0x339596C5AC4F1FB1), x ^ 0x3A486CEBCEFA48B7)
}

pub fn run(seed: u64) -> u64 {
    let r = simulate(seed ^ 0xD0F1527C73B2EFBD);
    mix(r)
}
